"""Persistent SQLite storage for crawl state, records, link graph, and evidence."""

from __future__ import annotations

import json
from pathlib import Path
import sqlite3
from typing import Any, Sequence

from src.models import (
    InternalLinkEdge,
    SEOIssue,
)
from src.transport import classify_transport_error

REDIRECT_STATUSES = (301, 302, 303, 307, 308)

# Issues generated by post_crawl_sync from the link graph; cleared and rebuilt on every run.
LINK_ISSUE_NAMES = (
    "Broken Internal Link",
    "Duplicate Content Detected",
    "Malformed Relative Link",
    "Internal Link to Redirect",
)

# Issues generated by the post-crawl site-context audit (seo_auditor.audit_site_context).
# Also includes the legacy per-page names so that re-running the post-crawl stage on an
# older database replaces the URL-heuristic versions.
SITE_CONTEXT_ISSUE_NAMES = (
    "Missing LocalBusiness / Clinic Schema",
    "Indexable Thank-You / Confirmation Page",
    "Indexable Prototype / Staging Page",
    "Prototype / Staging Page",
    "Staging Hostname Reference",
    "Clinic Page Missing Visible Address",
    "Closed/moved clinic page: confirm indexing and schema approach",
    "Ownership transferred: confirm LocalBusiness schema",
    "Stale Status Notice",
    "Duplicate Clinic Address",
    "Slow Server Response (sequential sample)",
)

_PAGE_COLUMN_MIGRATIONS = {
    "page_type": "TEXT",
    "location_status": "TEXT",
}
_LINK_COLUMN_MIGRATIONS = {
    "malformed_relative": "INTEGER DEFAULT 0",
    "intended_host": "TEXT",
    "raw_href": "TEXT",
    "target_error_type": "TEXT",
}


def is_broken_target(status: int | None, error_type: str | None) -> bool:
    """A link target is broken when it returned HTTP >= 400 or failed at transport level.

    Status 0 alone (e.g. a challenge page or exhausted retries with no transport error)
    is "not verified", not broken.
    """
    return bool(error_type) or (status is not None and status >= 400)


def _edge_value(link: InternalLinkEdge | dict[str, Any], key: str, default: Any = None) -> Any:
    if isinstance(link, InternalLinkEdge):
        return getattr(link, key, default)
    return link.get(key, default)


class SQLiteStorage:
    """Manages an ACID, WAL-mode SQLite database for checkpointing crawl results and link graph."""

    def __init__(self, db_path: Path | str) -> None:
        self.db_path = Path(db_path)
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self._init_db()

    def _get_connection(self) -> sqlite3.Connection:
        conn = sqlite3.connect(str(self.db_path), timeout=30.0)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("PRAGMA synchronous=NORMAL;")
        conn.execute("PRAGMA busy_timeout=30000;")
        return conn

    def _init_db(self) -> None:
        with self._get_connection() as conn:
            conn.executescript("""
            CREATE TABLE IF NOT EXISTS crawl_metadata (\n                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS pages (
                url TEXT PRIMARY KEY,
                domain TEXT,
                depth INTEGER,
                status_code INTEGER,
                title TEXT,
                meta_description TEXT,
                canonical_url TEXT,
                word_count INTEGER,
                internal_outlinks_count INTEGER,
                external_outlinks_count INTEGER,
                response_time_ms INTEGER DEFAULT 0,
                page_size_bytes INTEGER DEFAULT 0,
                inlinks_count INTEGER DEFAULT 0,
                is_ssr INTEGER,
                raw_json TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS internal_links (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                source_url TEXT NOT NULL,
                target_url TEXT NOT NULL,
                anchor_text TEXT,
                placement TEXT,
                is_nofollow INTEGER DEFAULT 0,
                target_status INTEGER
            );

            CREATE TABLE IF NOT EXISTS seo_issues (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                url TEXT NOT NULL,
                severity TEXT NOT NULL,
                category TEXT NOT NULL,
                issue TEXT NOT NULL,
                details TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS citations (
                url TEXT PRIMARY KEY,
                platform TEXT,
                label TEXT,
                status TEXT,
                nap_match TEXT,
                confidence TEXT,
                proxy_port INTEGER,
                raw_json TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS serp (
                query TEXT,
                location TEXT,
                raw_json TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS evidence (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                claim_type TEXT,
                source_url TEXT,
                timestamp TEXT,
                http_status INTEGER,
                dom_selector TEXT,
                verbatim_text TEXT,
                hash_sha256 TEXT,
                raw_json TEXT NOT NULL
            );

            CREATE INDEX IF NOT EXISTS idx_pages_domain ON pages(domain);
            CREATE INDEX IF NOT EXISTS idx_internal_links_source ON internal_links(source_url);
            CREATE INDEX IF NOT EXISTS idx_internal_links_target ON internal_links(target_url);
            CREATE INDEX IF NOT EXISTS idx_seo_issues_url ON seo_issues(url);
            CREATE INDEX IF NOT EXISTS idx_evidence_source ON evidence(source_url);

            CREATE TABLE IF NOT EXISTS duplicate_pairs (
                url_a TEXT NOT NULL,
                url_b TEXT NOT NULL,
                similarity REAL NOT NULL
            );

            CREATE TABLE IF NOT EXISTS google_ga4_pages (
                property_id TEXT NOT NULL,
                metric_date TEXT NOT NULL,
                landing_page TEXT NOT NULL,
                channel_group TEXT NOT NULL,
                sessions INTEGER NOT NULL DEFAULT 0,
                engaged_sessions INTEGER NOT NULL DEFAULT 0,
                active_users INTEGER NOT NULL DEFAULT 0,
                key_events REAL NOT NULL DEFAULT 0.0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (property_id, metric_date, landing_page, channel_group)
            );

            CREATE TABLE IF NOT EXISTS google_gsc_pages (
                site_url TEXT NOT NULL,
                metric_date TEXT NOT NULL,
                page_url TEXT NOT NULL,
                clicks REAL NOT NULL DEFAULT 0.0,
                impressions REAL NOT NULL DEFAULT 0.0,
                ctr REAL NOT NULL DEFAULT 0.0,
                position REAL NOT NULL DEFAULT 0.0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                PRIMARY KEY (site_url, metric_date, page_url)
            );

            CREATE TABLE IF NOT EXISTS google_gbp_locations (
                location_name TEXT PRIMARY KEY,
                account_id TEXT NOT NULL,
                title TEXT NOT NULL DEFAULT '',
                store_code TEXT NOT NULL DEFAULT '',
                website_uri TEXT NOT NULL DEFAULT '',
                raw_json TEXT NOT NULL,
                metric_start_date TEXT NOT NULL DEFAULT '',
                metric_end_date TEXT NOT NULL DEFAULT '',
                metrics_json TEXT NOT NULL DEFAULT '{}',
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );

            CREATE INDEX IF NOT EXISTS idx_google_ga4_landing_page ON google_ga4_pages(landing_page);
            CREATE INDEX IF NOT EXISTS idx_google_gsc_page_url ON google_gsc_pages(page_url);
            CREATE INDEX IF NOT EXISTS idx_google_gbp_website_uri ON google_gbp_locations(website_uri);
            """)
            self._ensure_columns(conn, "pages", _PAGE_COLUMN_MIGRATIONS)
            self._ensure_columns(conn, "internal_links", _LINK_COLUMN_MIGRATIONS)

    @staticmethod
    def _ensure_columns(conn: sqlite3.Connection, table: str, columns: dict[str, str]) -> None:
        """Idempotent additive migration: ADD COLUMN for any column missing from table."""
        existing = {r[1] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()}
        for name, decl in columns.items():
            if name not in existing:
                conn.execute(f"ALTER TABLE {table} ADD COLUMN {name} {decl}")

    def set_meta(self, key: str, value: Any) -> None:
        with self._get_connection() as conn:
            conn.execute(
                "INSERT OR REPLACE INTO crawl_metadata (key, value) VALUES (?, ?)",
                (key, json.dumps(value)),
            )

    def get_meta(self, key: str) -> Any:
        with self._get_connection() as conn:
            row = conn.execute("SELECT value FROM crawl_metadata WHERE key = ?", (key,)).fetchone()
            return json.loads(row["value"]) if row else None

    def save_page(self, page_data: dict[str, Any], domain: str = "", depth: int = 0) -> None:
        url = page_data.get("url", "")
        with self._get_connection() as conn:
            conn.execute(
                """
                INSERT OR REPLACE INTO pages (
                    url, domain, depth, status_code, title, meta_description,
                    canonical_url, word_count, internal_outlinks_count,
                    external_outlinks_count, response_time_ms, page_size_bytes,
                    inlinks_count, is_ssr, raw_json, page_type, location_status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    url,
                    domain,
                    depth,
                    page_data.get("status_code", 200),
                    page_data.get("title", ""),
                    page_data.get("meta_description", ""),
                    page_data.get("canonical_url", ""),
                    page_data.get("word_count", 0),
                    page_data.get("internal_outlinks_count", 0),
                    page_data.get("external_outlinks_count", 0),
                    page_data.get("response_time_ms", 0),
                    page_data.get("page_size_bytes", 0),
                    page_data.get("inlinks_count", 0),
                    1 if page_data.get("is_ssr", True) else 0,
                    json.dumps(page_data, ensure_ascii=False),
                    page_data.get("page_type") or None,
                    page_data.get("location_status") or None,
                ),
            )

    def save_classifications(self, classifications: dict[str, dict[str, Any]]) -> None:
        """Persist post-crawl page classification into page columns and raw_json."""
        if not classifications:
            return
        with self._get_connection() as conn:
            rows = conn.execute("SELECT url, raw_json FROM pages").fetchall()
            updates = []
            for r in rows:
                fields = classifications.get(r["url"])
                if fields is None:
                    continue
                data = json.loads(r["raw_json"])
                data.update(fields)
                updates.append((
                    fields.get("page_type") or None,
                    fields.get("location_status") or None,
                    json.dumps(data, ensure_ascii=False),
                    r["url"],
                ))
            conn.executemany(
                "UPDATE pages SET page_type = ?, location_status = ?, raw_json = ? WHERE url = ?",
                updates,
            )

    def save_duplicate_pairs(self, pairs: list[tuple[str, str, float]]) -> None:
        """Replace stored duplicate-content edges (used to build duplicate clusters)."""
        with self._get_connection() as conn:
            conn.execute("DELETE FROM duplicate_pairs")
            conn.executemany(
                "INSERT INTO duplicate_pairs (url_a, url_b, similarity) VALUES (?, ?, ?)",
                [(a, b, float(sim)) for a, b, sim in pairs],
            )

    def fetch_duplicate_pairs(self) -> list[tuple[str, str, float]]:
        with self._get_connection() as conn:
            rows = conn.execute("SELECT url_a, url_b, similarity FROM duplicate_pairs ORDER BY rowid").fetchall()
            return [(r["url_a"], r["url_b"], float(r["similarity"])) for r in rows]

    def save_internal_links_batch(self, links: Sequence[InternalLinkEdge | dict[str, Any]]) -> None:
        if not links:
            return
        source_urls = {_edge_value(l, "source_url", "") for l in links}
        rows = [
            (
                _edge_value(l, "source_url", ""),
                _edge_value(l, "target_url", ""),
                _edge_value(l, "anchor_text", ""),
                _edge_value(l, "placement", "body") or "body",
                1 if _edge_value(l, "is_nofollow", False) else 0,
                _edge_value(l, "target_status"),
                1 if _edge_value(l, "malformed_relative", False) else 0,
                _edge_value(l, "intended_host", "") or "",
                _edge_value(l, "raw_href", "") or "",
                _edge_value(l, "target_error_type", "") or "",
            )
            for l in links
        ]
        with self._get_connection() as conn:
            for src in source_urls:
                if src:
                    conn.execute("DELETE FROM internal_links WHERE source_url = ?", (src,))
            conn.executemany(
                """
                INSERT INTO internal_links (
                    source_url, target_url, anchor_text, placement, is_nofollow, target_status,
                    malformed_relative, intended_host, raw_href, target_error_type
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )

    def save_seo_issues_batch(self, issues: Sequence[SEOIssue | dict[str, Any]]) -> None:
        if not issues:
            return
        rows = [
            (
                i.url if isinstance(i, SEOIssue) else i.get("url", ""),
                i.severity if isinstance(i, SEOIssue) else i.get("severity", "warning"),
                i.category if isinstance(i, SEOIssue) else i.get("category", "SEO"),
                i.issue if isinstance(i, SEOIssue) else i.get("issue", ""),
                i.details if isinstance(i, SEOIssue) else i.get("details", ""),
            )
            for i in issues
        ]
        with self._get_connection() as conn:
            conn.executemany(
                """
                INSERT INTO seo_issues (url, severity, category, issue, details)
                VALUES (?, ?, ?, ?, ?)
                """,
                rows,
            )

    def backfill_link_statuses_from_pages(self) -> None:
        """Backfill target_status on internal_links from crawled pages (exact or trailing-slash matched)."""
        with self._get_connection() as conn:
            conn.execute("""
            UPDATE internal_links
            SET target_status = COALESCE(
                (SELECT p.status_code FROM pages p WHERE p.url = internal_links.target_url LIMIT 1),
                (SELECT p.status_code FROM pages p WHERE rtrim(p.url, '/') = rtrim(internal_links.target_url, '/') LIMIT 1)
            )
            WHERE target_status IS NULL
            """)

    def post_crawl_sync(
        self,
        duplicate_issues: dict[str, SEOIssue] | None = None,
        context_issues: dict[str, list[SEOIssue]] | None = None,
    ) -> None:
        """Run post-crawl link status backfill, compute inlinks, and rebuild link-graph issues.

        - Broken targets: HTTP >= 400, a transport failure (TLS/DNS/timeout/...), or a
          redirect whose final hop returned >= 400 or failed at the transport level.
        - Malformed relative links (WS1), internal links to redirects (WS7) and duplicate
          content issues are rebuilt idempotently.
        - context_issues (from seo_auditor.audit_site_context) replace any previously
          stored site-context issues when provided.
        """
        self.backfill_link_statuses_from_pages()

        with self._get_connection() as conn:
            # Parse every page's raw_json once; reused by all passes below
            page_rows = [
                (r["url"], json.loads(r["raw_json"]))
                for r in conn.execute("SELECT url, raw_json FROM pages").fetchall()
            ]
            redirect_broken_targets: dict[str, int] = {}
            transport_broken_targets: dict[str, str] = {}
            redirect_final_map: dict[str, str] = {}
            for u, p_data in page_rows:
                st = int(p_data.get("status_code", 0) or 0)
                r_target_st = p_data.get("redirect_target_status")
                f_url = p_data.get("final_url") or ""
                t_err = p_data.get("transport_error") or ""
                if st in REDIRECT_STATUSES:
                    if f_url and f_url != u:
                        redirect_final_map[u.rstrip("/")] = f_url.rstrip("/")
                    if isinstance(r_target_st, int) and r_target_st >= 400:
                        redirect_broken_targets[u] = r_target_st
                if t_err and st != 200:
                    err_type = p_data.get("transport_error_type") or classify_transport_error(t_err)
                    transport_broken_targets[u] = err_type or "other"

            for r_url, r_st in redirect_broken_targets.items():
                conn.execute(
                    "UPDATE internal_links SET target_status = ? WHERE target_url = ? OR rtrim(target_url, '/') = ?",
                    (r_st, r_url, r_url.rstrip("/")),
                )
            for t_url, err_type in transport_broken_targets.items():
                conn.execute(
                    """
                    UPDATE internal_links SET target_status = 0, target_error_type = ?
                    WHERE target_url = ? OR rtrim(target_url, '/') = ?
                    """,
                    (err_type, t_url, t_url.rstrip("/")),
                )

            # Inlinks per page (exact + trailing-slash normalized + redirect destination credit)
            inlink_rows = conn.execute("""
            SELECT target_url, COUNT(*) as cnt
            FROM internal_links
            GROUP BY target_url
            """).fetchall()
            inlinks_exact: dict[str, int] = {}
            inlinks_rtrim: dict[str, int] = {}
            for r in inlink_rows:
                t_url = r["target_url"] or ""
                cnt = int(r["cnt"])
                inlinks_exact[t_url] = inlinks_exact.get(t_url, 0) + cnt
                norm_key = t_url.rstrip("/")
                inlinks_rtrim[norm_key] = inlinks_rtrim.get(norm_key, 0) + cnt
                if norm_key in redirect_final_map:
                    dest_key = redirect_final_map[norm_key]
                    if dest_key != norm_key:
                        inlinks_rtrim[dest_key] = inlinks_rtrim.get(dest_key, 0) + cnt

            # Broken outlinks, deduplicated per (source_url, target_url)
            broken_rows = conn.execute("""
            SELECT source_url, target_url,
                   MIN(target_status) AS target_status,
                   MAX(COALESCE(target_error_type, '')) AS error_type,
                   MIN(COALESCE(malformed_relative, 0)) AS all_malformed
            FROM internal_links
            WHERE target_status >= 400
               OR (target_error_type IS NOT NULL AND target_error_type != '')
            GROUP BY source_url, target_url
            ORDER BY source_url, target_url
            """).fetchall()
            broken_map: dict[str, list[dict[str, Any]]] = {}
            for br in broken_rows:
                status = br["target_status"]
                err = br["error_type"] or ""
                broken_map.setdefault(br["source_url"], []).append({
                    "target_url": br["target_url"],
                    "target_status": status,
                    "error_type": err,
                    "malformed": bool(br["all_malformed"]),
                })

            # Malformed relative links (WS1)
            malformed_rows = conn.execute("""
            SELECT source_url, target_url,
                   MIN(raw_href) AS raw_href, MIN(intended_host) AS intended_host,
                   MIN(target_status) AS target_status,
                   MAX(COALESCE(target_error_type, '')) AS error_type
            FROM internal_links
            WHERE malformed_relative = 1
            GROUP BY source_url, target_url
            ORDER BY source_url, target_url
            """).fetchall()
            malformed_map: dict[str, list[sqlite3.Row]] = {}
            for mr in malformed_rows:
                malformed_map.setdefault(mr["source_url"], []).append(mr)

            # Internal links to redirects (WS7)
            redirect_rows = conn.execute("""
            SELECT source_url, target_url, MIN(target_status) AS target_status
            FROM internal_links
            WHERE target_status IN (301, 302, 303, 307, 308)
              AND COALESCE(malformed_relative, 0) = 0
              AND (target_error_type IS NULL OR target_error_type = '')
            GROUP BY source_url, target_url
            ORDER BY source_url, target_url
            """).fetchall()
            page_final: dict[str, str] = {}
            for u, p_data in page_rows:
                page_final[u] = p_data.get("final_url") or ""
                page_final.setdefault(u.rstrip("/"), p_data.get("final_url") or "")
            redirect_map: dict[str, list[tuple[str, int, str]]] = {}
            for rr in redirect_rows:
                t = rr["target_url"]
                final = page_final.get(t) or page_final.get(t.rstrip("/")) or ""
                redirect_map.setdefault(rr["source_url"], []).append((t, int(rr["target_status"]), final))

            # Clear previously synced post-crawl issues so re-runs are idempotent
            names_to_clear = list(LINK_ISSUE_NAMES)
            if context_issues is not None:
                names_to_clear += list(SITE_CONTEXT_ISSUE_NAMES)
                for iss_list in context_issues.values():
                    names_to_clear += [i.issue for i in iss_list]
            names_to_clear = sorted(set(names_to_clear))
            placeholders = ",".join("?" for _ in names_to_clear)
            conn.execute(f"DELETE FROM seo_issues WHERE issue IN ({placeholders})", names_to_clear)
            clear_set = set(names_to_clear)

            updated_pages = []
            new_post_crawl_issues: list[tuple[str, str, str, str, str]] = []

            def _add(issue_list: list[dict[str, Any]], iss: dict[str, Any]) -> None:
                issue_list.append(iss)
                new_post_crawl_issues.append((
                    iss["url"], iss["severity"], iss["category"], iss["issue"], iss["details"],
                ))

            for u, data in page_rows:
                inlinks_val = max(inlinks_exact.get(u, 0), inlinks_rtrim.get(u.rstrip("/"), 0))
                data["inlinks_count"] = inlinks_val
                b_details = broken_map.get(u, [])
                data["broken_outlinks"] = [b["target_url"] for b in b_details]
                data["broken_outlink_details"] = [
                    {"target_url": b["target_url"], "target_status": b["target_status"], "error_type": b["error_type"]}
                    for b in b_details
                ]

                existing_issues = [
                    iss for iss in data.get("issues", []) if iss.get("issue") not in clear_set
                ]

                for b in b_details:
                    if b["malformed"]:
                        continue  # reported as "Malformed Relative Link" (error) below
                    reason = f"HTTP {b['target_status']}" if b["target_status"] else "transport failure"
                    if b["error_type"]:
                        reason += f", {b['error_type']}"
                    _add(existing_issues, {
                        "url": u,
                        "severity": "error",
                        "category": "Links",
                        "issue": "Broken Internal Link",
                        "details": f"Page links to broken internal URL: {b['target_url']} ({reason})",
                    })

                for mr in malformed_map.get(u, []):
                    st = mr["target_status"]
                    err = mr["error_type"] or ""
                    is_broken = is_broken_target(st, err)
                    if err:
                        outcome = f"transport failure ({err})"
                    elif st is None or st == 0:
                        outcome = "target not verified"
                    else:
                        outcome = f"HTTP {st}"
                    _add(existing_issues, {
                        "url": u,
                        "severity": "error" if is_broken else "warning",
                        "category": "Links",
                        "issue": "Malformed Relative Link",
                        "details": (
                            f'href="{mr["raw_href"]}" has no scheme, so browsers resolve it to '
                            f'{mr["target_url"]} ({outcome}) instead of the intended host '
                            f'{mr["intended_host"]}'
                        ),
                    })

                for t, st, final in redirect_map.get(u, []):
                    _add(existing_issues, {
                        "url": u,
                        "severity": "info",
                        "category": "Links",
                        "issue": "Internal Link to Redirect",
                        "details": f"Page links to {t}, which redirects (HTTP {st}) to {final or 'another URL'}",
                    })

                if duplicate_issues and u in duplicate_issues:
                    _add(existing_issues, duplicate_issues[u].model_dump())

                if context_issues and u in context_issues:
                    for ci in context_issues[u]:
                        _add(existing_issues, ci.model_dump())

                data["issues"] = existing_issues
                updated_pages.append((data["inlinks_count"], json.dumps(data, ensure_ascii=False), u))

            conn.executemany(
                "UPDATE pages SET inlinks_count = ?, raw_json = ? WHERE url = ?",
                updated_pages,
            )

            if new_post_crawl_issues:
                conn.executemany(
                    """
                    INSERT INTO seo_issues (url, severity, category, issue, details)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    new_post_crawl_issues,
                )

    def save_citation(self, citation_data: dict[str, Any]) -> None:
        with self._get_connection() as conn:
            conn.execute(
                """
                INSERT OR REPLACE INTO citations (
                    url, platform, label, status, nap_match, confidence, proxy_port, raw_json
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    citation_data.get("url", ""),
                    citation_data.get("platform", ""),
                    citation_data.get("label", ""),
                    citation_data.get("status", ""),
                    citation_data.get("nap_match", ""),
                    citation_data.get("confidence", ""),
                    citation_data.get("proxy_port"),
                    json.dumps(citation_data, ensure_ascii=False),
                ),
            )

    def save_serp(self, query: str, location: str, serp_data: dict[str, Any]) -> None:
        with self._get_connection() as conn:
            conn.execute(
                "INSERT INTO serp (query, location, raw_json) VALUES (?, ?, ?)",
                (query, location, json.dumps(serp_data, ensure_ascii=False)),
            )

    def save_evidence_batch(self, evidence_list: list[dict[str, Any]]) -> None:
        if not evidence_list:
            return
        rows = [
            (
                e.get("claim_type", ""),
                e.get("source_url", ""),
                e.get("timestamp", ""),
                e.get("http_status", 0),
                e.get("dom_selector", ""),
                e.get("verbatim_text", ""),
                e.get("hash_sha256", ""),
                json.dumps(e, ensure_ascii=False),
            )
            for e in evidence_list
        ]
        with self._get_connection() as conn:
            conn.executemany(
                """
                INSERT INTO evidence (
                    claim_type, source_url, timestamp, http_status,
                    dom_selector, verbatim_text, hash_sha256, raw_json
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )

    def get_completed_urls(self, mode: str) -> set[str]:
        """Fetch all URLs that have already been persisted."""
        table = "pages" if mode == "competitor" else ("citations" if mode == "citations" else "serp")
        if table == "serp":
            return set()
        with self._get_connection() as conn:
            rows = conn.execute(f"SELECT url FROM {table}").fetchall()
            return {r["url"] for r in rows}

    def fetch_all_pages(self) -> list[dict[str, Any]]:
        with self._get_connection() as conn:
            rows = conn.execute("SELECT raw_json FROM pages ORDER BY rowid ASC").fetchall()
            return [json.loads(r["raw_json"]) for r in rows]

    def fetch_all_internal_links(self) -> list[dict[str, Any]]:
        """Fetch all stored internal link edges with status and anchor text."""
        with self._get_connection() as conn:
            rows = conn.execute(
                """
                SELECT source_url, target_url, anchor_text, placement, is_nofollow, target_status,
                       malformed_relative, intended_host, raw_href, target_error_type
                FROM internal_links ORDER BY id ASC
                """
            ).fetchall()
            return [
                {
                    "source_url": r["source_url"],
                    "target_url": r["target_url"],
                    "anchor_text": r["anchor_text"] or "",
                    "placement": r["placement"] or "body",
                    "is_nofollow": bool(r["is_nofollow"]),
                    "target_status": r["target_status"],
                    "malformed_relative": bool(r["malformed_relative"]),
                    "intended_host": r["intended_host"] or "",
                    "raw_href": r["raw_href"] or "",
                    "target_error_type": r["target_error_type"] or "",
                }
                for r in rows
            ]

    def get_unvisited_link_targets(self, malformed_only: bool = False) -> list[str]:
        """Distinct link targets whose status is still unknown after backfilling crawled pages.

        malformed_only restricts the result to malformed relative links, which are never
        queued for crawling and therefore always need a separate status check.
        """
        self.backfill_link_statuses_from_pages()
        where = "target_status IS NULL"
        if malformed_only:
            where += " AND malformed_relative = 1"
        with self._get_connection() as conn:
            rows = conn.execute(
                f"SELECT DISTINCT target_url FROM internal_links WHERE {where} ORDER BY target_url"
            ).fetchall()
            return [r["target_url"] for r in rows if r["target_url"]]

    def update_link_target_statuses(
        self,
        status_map: dict[str, int],
        error_map: dict[str, str] | None = None,
    ) -> None:
        """Update target_status (and optional transport error type) for specific target URLs."""
        if status_map:
            with self._get_connection() as conn:
                conn.executemany(
                    "UPDATE internal_links SET target_status = ? WHERE target_url = ?",
                    [(status, url) for url, status in status_map.items()],
                )
        if error_map:
            with self._get_connection() as conn:
                conn.executemany(
                    "UPDATE internal_links SET target_status = 0, target_error_type = ? WHERE target_url = ?",
                    [(err, url) for url, err in error_map.items()],
                )

    def fetch_all_citations(self) -> list[dict[str, Any]]:
        with self._get_connection() as conn:
            rows = conn.execute("SELECT raw_json FROM citations ORDER BY rowid ASC").fetchall()
            return [json.loads(r["raw_json"]) for r in rows]

    def fetch_all_serp(self) -> dict[str, Any] | None:
        with self._get_connection() as conn:
            row = conn.execute("SELECT raw_json FROM serp ORDER BY rowid DESC LIMIT 1").fetchone()
            return json.loads(row["raw_json"]) if row else None

    def fetch_all_evidence(self) -> list[dict[str, Any]]:
        with self._get_connection() as conn:
            rows = conn.execute("SELECT raw_json FROM evidence ORDER BY rowid ASC").fetchall()
            return [json.loads(r["raw_json"]) for r in rows]

    def count_results(self, mode: str) -> int:
        table = "pages" if mode == "competitor" else ("citations" if mode == "citations" else "serp")
        with self._get_connection() as conn:
            row = conn.execute(f"SELECT COUNT(*) as cnt FROM {table}").fetchone()
            return row["cnt"] if row else 0

